67.   constructor(
68.     private readonly policies: readonly DiscountPolicy[],
69.     private readonly mode: StackingMode = "sum",
70.   ) {
71.     if (policies.length === 0) {
72.       throw new Error("CompositeDiscountPolicy requires at least one policy");
73.     }
74.   }
75. 
76.   computeDiscountCents(subtotalCents: number): number {
77.     if (subtotalCents <= 0) return 0;
78.     if (this.mode === "sum") {
79.       let total = 0;
80.       for (const p of this.policies) {
81.         total += Math.max(0, p.computeDiscountCents(subtotalCents));
82.       }
83.       return total;
84.     }
85.     let remaining = subtotalCents;
86.     let total = 0;
87.     for (const p of this.policies) {
88.       const step = Math.min(
89.         Math.max(0, p.computeDiscountCents(remaining)),
90.         remaining,
91.       );
92.       remaining -= step;
93.       total += step;
94.     }
95.     return total;
96.   }
