describe("WeightBasedShippingCalculator", () => {
  describe("constructor validation", () => {
    it("rejects empty brackets", () => {
      expect(() => new WeightBasedShippingCalculator([])).toThrow(
        "at least one weight bracket is required",
      );
    });

    it("rejects non-positive upToGrams", () => {
      expect(
        () => new WeightBasedShippingCalculator([{ upToGrams: 0, costCents: 500 }]),
      ).toThrow(RangeError);
    });

    it("rejects negative costCents", () => {
      expect(
        () => new WeightBasedShippingCalculator([{ upToGrams: 1000, costCents: -1 }]),
      ).toThrow(RangeError);
    });

    it("rejects non-integer upToGrams", () => {
      expect(
        () => new WeightBasedShippingCalculator([{ upToGrams: 1.5, costCents: 500 }]),
      ).toThrow(RangeError);
    });

    it("rejects negative overflowCostCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator(
            [{ upToGrams: 1000, costCents: 500 }],
            -1,
          ),
      ).toThrow(RangeError);
    });

    it("rejects non-integer overflowCostCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator(
            [{ upToGrams: 1000, costCents: 500 }],
            5.5,
          ),
      ).toThrow(RangeError);
    });
  });

  describe("computeShippingCents", () => {
    const calc = new WeightBasedShippingCalculator(
      [
        { upToGrams: 500, costCents: 300 },
        { upToGrams: 2000, costCents: 700 },
        { upToGrams: 5000, costCents: 1200 },
      ],
      2000,
    );

    it("returns 0 for empty cart", () => {
      expect(calc.computeShippingCents([], 0)).toBe(0);
    });

    it("returns 0 when total weight is 0", () => {
      expect(calc.computeShippingCents([makeLine("a", undefined, 2)], 1000)).toBe(0);
    });

    it("selects the first bracket when weight is at boundary", () => {
      // weight = 500g → first bracket
      expect(calc.computeShippingCents([makeLine("a", 500, 1)], 1000)).toBe(300);
    });

    it("selects the correct bracket for weight within range", () => {
      // weight = 501g → second bracket
      expect(calc.computeShippingCents([makeLine("a", 501, 1)], 1000)).toBe(700);
    });

    it("selects last bracket at exact boundary", () => {
      // weight = 5000g → third bracket
      expect(calc.computeShippingCents([makeLine("a", 5000, 1)], 1000)).toBe(1200);
    });

    it("uses overflow cost when weight exceeds all brackets", () => {
      // weight = 5001g → overflow = 2000
      expect(calc.computeShippingCents([makeLine("a", 5001, 1)], 1000)).toBe(2000);
    });

    it("falls back to heaviest bracket cost when no overflow is configured", () => {
      const calcNoOverflow = new WeightBasedShippingCalculator([
        { upToGrams: 500, costCents: 300 },
        { upToGrams: 2000, costCents: 700 },
      ]);
      // weight = 3000g → overflow = last bracket cost (700)
      expect(calcNoOverflow.computeShippingCents([makeLine("a", 3000, 1)], 1000)).toBe(700);
    });

    it("sorts brackets regardless of input order", () => {
      const unordered = new WeightBasedShippingCalculator([
        { upToGrams: 2000, costCents: 700 },
        { upToGrams: 500, costCents: 300 },
      ]);
      // weight = 400 → should hit the 500g bracket (300)
      expect(unordered.computeShippingCents([makeLine("a", 400, 1)], 1000)).toBe(300);
    });

    it("sums weight across multiple lines", () => {
      // 250*2 = 500 (boundary of first bracket)
      const lines = [makeLine("a", 250, 2)];
      expect(calc.computeShippingCents(lines, 1000)).toBe(300);
    });
  });
});

