describe("Cart.checkout()", () => {
  it("returns totals and lines for a simple checkout without collaborators", async () => {
    const cart = new Cart();
    cart.add(widgetProduct(), 2);
    const result = await cart.checkout();
    expect(result.totals.subtotalCents).toBe(2000);
    expect(result.lines).toHaveLength(1);
    expect(result.lines[0]!.quantity).toBe(2);
  });

  describe("price refresh", () => {
    it("updates prices from the PriceFetcher before computing totals", async () => {
      const priceFetcher: PriceFetcher = {
        fetchPriceCents: vi.fn().mockResolvedValue(1500),
      };
      const cart = new Cart();
      cart.add(widgetProduct(), 2);
      const result = await cart.checkout({ priceFetcher });
      expect(result.totals.subtotalCents).toBe(3000); // 1500 * 2
      expect(result.lines[0]!.product.unitPriceCents).toBe(1500);
    });

    it("propagates PriceFetcher errors", async () => {
      const priceFetcher: PriceFetcher = {
        fetchPriceCents: vi.fn().mockRejectedValue(new Error("price service down")),
      };
      const cart = new Cart();
      cart.add(widgetProduct(), 1);
      await expect(cart.checkout({ priceFetcher })).rejects.toThrow("price service down");
    });
  });

  describe("inventory check", () => {
    it("succeeds when all items are available", async () => {
      const inventoryChecker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({ available: true }),
      };
      const cart = new Cart();
      cart.add(widgetProduct(), 1);
      const result = await cart.checkout({ inventoryChecker });
      expect(result.totals.subtotalCents).toBe(1000);
    });

    it("throws InventoryError when item is unavailable", async () => {
      const inventoryChecker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({
          available: false,
          reason: "discontinued",
        }),
      };
      const cart = new Cart();
      cart.add(widgetProduct(), 3);
      try {
        await cart.checkout({ inventoryChecker });
        expect.fail("should have thrown");
      } catch (err) {
        expect(err).toBeInstanceOf(InventoryError);
        const invErr = err as InventoryError;
        expect(invErr.productId).toBe("widget");
        expect(invErr.requested).toBe(3);
        expect(invErr.message).toBe("discontinued");
      }
    });

    it("throws InventoryError for partial-stock denial", async () => {
      const inventoryChecker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({
          available: true,
          availableQuantity: 2,
        }),
      };
      const cart = new Cart();
      cart.add(widgetProduct(), 5);
      try {
        await cart.checkout({ inventoryChecker });
        expect.fail("should have thrown");
      } catch (err) {
        expect(err).toBeInstanceOf(InventoryError);
        const invErr = err as InventoryError;
        expect(invErr.productId).toBe("widget");
        expect(invErr.requested).toBe(5);
        expect(invErr.available).toBe(2);
      }
    });

    it("checks inventory for each line item", async () => {
      const inventoryChecker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({ available: true }),
      };
      const cart = new Cart();
      cart.add(widgetProduct(), 1);
      cart.add(gadgetProduct(), 2);
      await cart.checkout({ inventoryChecker });
      expect(inventoryChecker.check).toHaveBeenCalledTimes(2);
    });

    it("stops at first denial with multiple items", async () => {
      const inventoryChecker: InventoryChecker = {
        check: vi
          .fn()
          .mockResolvedValueOnce({ available: true })
          .mockResolvedValueOnce({ available: false, reason: "out of stock" }),
      };
      const cart = new Cart();
      cart.add(widgetProduct(), 1);
      cart.add(gadgetProduct(), 2);
      await expect(cart.checkout({ inventoryChecker })).rejects.toThrow(InventoryError);
    });

    it("generates a default message when reason is not provided", async () => {
      const inventoryChecker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({
          available: false,
          availableQuantity: 0,
        }),
      };
      const cart = new Cart();
      cart.add(widgetProduct(), 2);
      try {
        await cart.checkout({ inventoryChecker });
        expect.fail("should have thrown");
      } catch (err) {
        const invErr = err as InventoryError;
        expect(invErr.message).toContain("widget");
        expect(invErr.message).toContain("2");
      }
    });
  });

  describe("async tax provider", () => {
    it("uses AsyncTaxRateProvider to compute tax", async () => {
      const asyncTaxProvider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockResolvedValue(0.10),
      };
      const cart = new Cart({ region: "US" });
      cart.add(widgetProduct(), 1); // subtotal 1000
      const result = await cart.checkout({ asyncTaxProvider });
      expect(result.totals.taxCents).toBe(100);
      expect(asyncTaxProvider.getRate).toHaveBeenCalledWith("US");
    });

    it("async tax is computed on discounted subtotal", async () => {
      const discount: DiscountPolicy = {
        computeDiscountCents: vi.fn().mockReturnValue(200),
      };
      const asyncTaxProvider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockResolvedValue(0.10),
      };
      const cart = new Cart({ discountPolicy: discount, region: "US" });
      cart.add(widgetProduct(), 1); // subtotal 1000, discount 200, discounted 800
      const result = await cart.checkout({ asyncTaxProvider });
      expect(result.totals.taxCents).toBe(80); // 10% of 800
    });

    it("propagates async tax provider errors", async () => {
      const asyncTaxProvider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockRejectedValue(new Error("rate service down")),
      };
      const cart = new Cart();
      cart.add(widgetProduct(), 1);
      await expect(cart.checkout({ asyncTaxProvider })).rejects.toThrow("rate service down");
    });
  });

  describe("full pipeline with all collaborators", () => {
    it("price refresh → inventory check → async tax → totals", async () => {
      const discount: DiscountPolicy = {
        computeDiscountCents: vi.fn().mockReturnValue(100),
      };
      const shipping: ShippingCalculator = {
        computeShippingCents: vi.fn().mockReturnValue(500),
      };
      const priceFetcher: PriceFetcher = {
        fetchPriceCents: vi.fn().mockResolvedValue(1200),
      };
      const inventoryChecker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({ available: true }),
      };
      const asyncTaxProvider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockResolvedValue(0.08),
      };

      const cart = new Cart({
        discountPolicy: discount,
        shippingCalculator: shipping,
        region: "US-TX",
      });
      cart.add(widgetProduct(), 2);

      const result = await cart.checkout({
        priceFetcher,
        inventoryChecker,
        asyncTaxProvider,
      });

      // subtotal: 1200 * 2 = 2400
      expect(result.totals.subtotalCents).toBe(2400);
      // discount: clamped(100) = 100
      expect(result.totals.discountCents).toBe(100);
      // discountedSubtotal: 2400 - 100 = 2300
      // tax: floor(2300 * 0.08) = floor(184) = 184
      expect(result.totals.taxCents).toBe(184);
      // shipping: 500
      expect(result.totals.shippingCents).toBe(500);
      // total: 2300 + 184 + 500 = 2984
      expect(result.totals.totalCents).toBe(2984);

      // Verify collaborators were called
      expect(priceFetcher.fetchPriceCents).toHaveBeenCalledWith("widget");
      expect(inventoryChecker.check).toHaveBeenCalledWith("widget", 2);
      expect(asyncTaxProvider.getRate).toHaveBeenCalledWith("US-TX");
    });
  });

  describe("checkout does not mutate cart state", () => {
    it("original cart lines are unchanged after price refresh", async () => {
      const priceFetcher: PriceFetcher = {
        fetchPriceCents: vi.fn().mockResolvedValue(9999),
      };
      const cart = new Cart();
      cart.add(widgetProduct(), 1);
      await cart.checkout({ priceFetcher });
      // Cart's internal price should still be the original
      expect(cart.totals().subtotalCents).toBe(1000);
    });
  });
});

import { describe, it, expect } from "vitest";
import {
  NoDiscountPolicy,
  PercentageDiscountPolicy,
  FixedAmountDiscountPolicy,
  CompositeDiscountPolicy,
} from "../src/pricing.ts";

describe("NoDiscountPolicy", () => {
  const policy = new NoDiscountPolicy();

  it.each([
    [0, 0],
    [1000, 0],
    [-500, 0],
    [999999, 0],
  ])("computeDiscountCents(%i) returns %i", (subtotal, expected) => {
    expect(policy.computeDiscountCents(subtotal)).toBe(expected);
  });
});

describe("PercentageDiscountPolicy", () => {
  describe("constructor validation", () => {
    it.each([
      [-1, "negative"],
      [101, "over 100"],
      [NaN, "NaN"],
      [Infinity, "Infinity"],
      [-Infinity, "-Infinity"],
    ])("rejects %d (%s)", (percent) => {
      expect(() => new PercentageDiscountPolicy(percent)).toThrow(RangeError);
    });

    it.each([0, 50, 100])("accepts valid percent %d", (percent) => {
      expect(() => new PercentageDiscountPolicy(percent)).not.toThrow();
    });
  });

  describe("computeDiscountCents", () => {
    it.each([
      [10, 1000, 100],
      [25, 999, 249],    // floors: 999 * 25 / 100 = 249.75 → 249
      [50, 1, 0],        // floors: 1 * 50 / 100 = 0.5 → 0
      [100, 5000, 5000],
      [0, 5000, 0],
    ])("%d%% of %d cents = %d", (percent, subtotal, expected) => {
      const policy = new PercentageDiscountPolicy(percent);
      expect(policy.computeDiscountCents(subtotal)).toBe(expected);
    });

    it("returns 0 for zero subtotal", () => {
      const policy = new PercentageDiscountPolicy(50);
      expect(policy.computeDiscountCents(0)).toBe(0);
    });

    it("returns 0 for negative subtotal", () => {
      const policy = new PercentageDiscountPolicy(50);
      expect(policy.computeDiscountCents(-100)).toBe(0);
    });
  });
});

describe("FixedAmountDiscountPolicy", () => {
  describe("constructor validation", () => {
    it.each([
      [-1, "negative"],
      [1.5, "non-integer"],
      [NaN, "NaN"],
    ])("rejects %d (%s)", (amount) => {
      expect(() => new FixedAmountDiscountPolicy(amount)).toThrow(RangeError);
    });

    it("accepts zero", () => {
      expect(() => new FixedAmountDiscountPolicy(0)).not.toThrow();
    });
  });

  describe("computeDiscountCents", () => {
    it("returns the fixed amount when subtotal exceeds it", () => {
      const policy = new FixedAmountDiscountPolicy(500);
      expect(policy.computeDiscountCents(1000)).toBe(500);
    });

    it("caps discount at subtotal when fixed amount exceeds subtotal", () => {
      const policy = new FixedAmountDiscountPolicy(500);
      expect(policy.computeDiscountCents(300)).toBe(300);
    });

    it("returns 0 for zero subtotal", () => {
      const policy = new FixedAmountDiscountPolicy(500);
      expect(policy.computeDiscountCents(0)).toBe(0);
    });

    it("returns 0 for negative subtotal", () => {
      const policy = new FixedAmountDiscountPolicy(500);
      expect(policy.computeDiscountCents(-100)).toBe(0);
    });

    it("returns exact subtotal when amounts match", () => {
      const policy = new FixedAmountDiscountPolicy(500);
      expect(policy.computeDiscountCents(500)).toBe(500);
    });
  });
});

describe("CompositeDiscountPolicy", () => {
  describe("constructor validation", () => {
    it("rejects empty policy list", () => {
      expect(() => new CompositeDiscountPolicy([])).toThrow(
        "CompositeDiscountPolicy requires at least one policy",
      );
    });
  });

  describe("sum mode", () => {
    it("sums discount amounts from all child policies against original subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [
          new PercentageDiscountPolicy(10), // 100
          new FixedAmountDiscountPolicy(200), // 200
        ],
        "sum",
      );
      // Both see subtotal 1000: 100 + 200 = 300
      expect(composite.computeDiscountCents(1000)).toBe(300);
    });

    it("can exceed subtotal (Cart clamps later)", () => {
      const composite = new CompositeDiscountPolicy(
        [
          new PercentageDiscountPolicy(80), // 800
          new FixedAmountDiscountPolicy(500), // 500
        ],
        "sum",
      );
      // 800 + 500 = 1300 (exceeds 1000, but CompositeDiscountPolicy doesn't clamp in sum mode)
      expect(composite.computeDiscountCents(1000)).toBe(1300);
    });

    it("returns 0 for zero subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10)],
        "sum",
      );
      expect(composite.computeDiscountCents(0)).toBe(0);
    });

    it("returns 0 for negative subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10)],
        "sum",
      );
      expect(composite.computeDiscountCents(-100)).toBe(0);
    });

    it("clamps negative child results to 0 before summing", () => {
      const negativePolicy = {
        computeDiscountCents: () => -50,
      };
      const composite = new CompositeDiscountPolicy(
        [negativePolicy, new FixedAmountDiscountPolicy(100)],
        "sum",
      );
      // -50 clamped to 0, + 100 = 100
      expect(composite.computeDiscountCents(1000)).toBe(100);
    });
  });

  describe("chain mode", () => {
    it("applies discounts sequentially to the remaining subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [
          new PercentageDiscountPolicy(10), // 10% of 1000 = 100, remaining 900
          new PercentageDiscountPolicy(10), // 10% of 900 = 90
        ],
        "chain",
      );
      // Total discount: 100 + 90 = 190
      expect(composite.computeDiscountCents(1000)).toBe(190);
    });

    it("ordering matters - larger discount first yields different result", () => {
      const smallThenLarge = new CompositeDiscountPolicy(
        [
          new PercentageDiscountPolicy(10),
          new PercentageDiscountPolicy(50),
        ],
        "chain",
      );
      const largeThenSmall = new CompositeDiscountPolicy(
        [
          new PercentageDiscountPolicy(50),
          new PercentageDiscountPolicy(10),
        ],
        "chain",
      );
      // 10% of 1000=100, remain 900; 50% of 900=450; total=550
      expect(smallThenLarge.computeDiscountCents(1000)).toBe(550);
      // 50% of 1000=500, remain 500; 10% of 500=50; total=550
      expect(largeThenSmall.computeDiscountCents(1000)).toBe(550);

      // With different rounding, ordering matters:
      // 10% of 999 = 99, remain 900; 50% of 900 = 450; total 549
      expect(smallThenLarge.computeDiscountCents(999)).toBe(549);
      // 50% of 999 = 499, remain 500; 10% of 500 = 50; total 549
      expect(largeThenSmall.computeDiscountCents(999)).toBe(549);
    });

    it("stops reducing once remaining hits 0", () => {
      const composite = new CompositeDiscountPolicy(
        [
          new FixedAmountDiscountPolicy(600),
          new FixedAmountDiscountPolicy(600),
        ],
        "chain",
      );
      // First takes 600 from 1000 → remaining 400; second takes min(600,400)=400
      expect(composite.computeDiscountCents(1000)).toBe(1000);
    });

    it("returns 0 for zero subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10)],
        "chain",
      );
      expect(composite.computeDiscountCents(0)).toBe(0);
    });
  });

  describe("defaults to sum mode", () => {
    it("uses sum when mode is omitted", () => {
      const composite = new CompositeDiscountPolicy([
        new FixedAmountDiscountPolicy(100),
        new FixedAmountDiscountPolicy(200),
      ]);
      expect(composite.computeDiscountCents(1000)).toBe(300);
    });
  });
});

