describe("refreshPrices", () => {
  const makeLines = (): CartLine[] => [
    { product: { id: "p1", name: "Widget", unitPriceCents: 1000 }, quantity: 2 },
    { product: { id: "p2", name: "Gadget", unitPriceCents: 2000, weightGrams: 300 }, quantity: 1 },
  ];

  it("updates unitPriceCents from the fetcher", async () => {
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn()
        .mockResolvedValueOnce(1100)
        .mockResolvedValueOnce(1900),
    };
    const lines = makeLines();
    const result = await refreshPrices(lines, fetcher);

    expect(result).toHaveLength(2);
    expect(result[0]!.product.unitPriceCents).toBe(1100);
    expect(result[0]!.quantity).toBe(2);
    expect(result[1]!.product.unitPriceCents).toBe(1900);
    expect(result[1]!.product.weightGrams).toBe(300); // preserves other fields
  });

  it("does not mutate the original lines", async () => {
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(999),
    };
    const lines = makeLines();
    await refreshPrices(lines, fetcher);
    expect(lines[0]!.product.unitPriceCents).toBe(1000); // unchanged
  });

  it("calls fetchPriceCents with each product id", async () => {
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(500),
    };
    const lines = makeLines();
    await refreshPrices(lines, fetcher);
    expect(fetcher.fetchPriceCents).toHaveBeenCalledWith("p1");
    expect(fetcher.fetchPriceCents).toHaveBeenCalledWith("p2");
    expect(fetcher.fetchPriceCents).toHaveBeenCalledTimes(2);
  });

  it("throws RangeError for negative price", async () => {
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(-1),
    };
    await expect(refreshPrices(makeLines(), fetcher)).rejects.toThrow(RangeError);
  });

  it("throws RangeError for non-integer price", async () => {
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(10.5),
    };
    await expect(refreshPrices(makeLines(), fetcher)).rejects.toThrow(RangeError);
  });

  it("propagates fetcher rejection", async () => {
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockRejectedValue(new Error("fetch failed")),
    };
    await expect(refreshPrices(makeLines(), fetcher)).rejects.toThrow("fetch failed");
  });

  it("returns empty array for empty input", async () => {
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn(),
    };
    const result = await refreshPrices([], fetcher);
    expect(result).toEqual([]);
    expect(fetcher.fetchPriceCents).not.toHaveBeenCalled();
  });
});

import { describe, it, expect, vi, beforeEach } from "vitest";
import { Cart } from "../src/cart.ts";
import type { CartConfig, CheckoutCollaborators } from "../src/cart.ts";
import type { Product } from "../src/product.ts";
import type { DiscountPolicy } from "../src/pricing.ts";
import type { TaxCalculator } from "../src/tax.ts";
import type { ShippingCalculator } from "../src/shipping.ts";
import type { PriceFetcher, InventoryChecker } from "../src/inventory.ts";
import type { AsyncTaxRateProvider } from "../src/tax.ts";
import { InventoryError } from "../src/inventory.ts";

// ── Helpers ──

const widgetProduct = (overrides: Partial<Product> = {}): Product => ({
  id: "widget",
  name: "Widget",
  unitPriceCents: 1000,
  ...overrides,
});

const gadgetProduct = (overrides: Partial<Product> = {}): Product => ({
  id: "gadget",
  name: "Gadget",
  unitPriceCents: 2000,
  weightGrams: 500,
  ...overrides,
});

// ── Cart.add / remove / updateQuantity / clear / itemCount ──

describe("Cart line management", () => {
  let cart: Cart;

  beforeEach(() => {
    cart = new Cart();
  });

  describe("add", () => {
    it("adds a product to the cart", () => {
      cart.add(widgetProduct(), 2);
      expect(cart.itemCount).toBe(2);
    });

    it("merges quantities when adding the same product", () => {
      cart.add(widgetProduct(), 2);
      cart.add(widgetProduct(), 3);
      expect(cart.itemCount).toBe(5);
    });

    it("tracks different products separately", () => {
      cart.add(widgetProduct(), 2);
      cart.add(gadgetProduct(), 1);
      expect(cart.itemCount).toBe(3);
    });

    it("rejects zero quantity", () => {
      expect(() => cart.add(widgetProduct(), 0)).toThrow(RangeError);
    });

    it("rejects negative quantity", () => {
      expect(() => cart.add(widgetProduct(), -1)).toThrow(RangeError);
    });

    it("rejects non-integer quantity", () => {
      expect(() => cart.add(widgetProduct(), 1.5)).toThrow(RangeError);
    });

    it("rejects negative unitPriceCents", () => {
      expect(() => cart.add(widgetProduct({ unitPriceCents: -1 }), 1)).toThrow(RangeError);
    });
  });

  describe("remove", () => {
    it("removes an existing product and returns true", () => {
      cart.add(widgetProduct(), 1);
      expect(cart.remove("widget")).toBe(true);
      expect(cart.itemCount).toBe(0);
    });

    it("returns false for unknown product id", () => {
      expect(cart.remove("unknown")).toBe(false);
    });
  });

  describe("updateQuantity", () => {
    it("updates quantity for an existing product", () => {
      cart.add(widgetProduct(), 2);
      cart.updateQuantity("widget", 5);
      expect(cart.itemCount).toBe(5);
    });

    it("removes the product when quantity is set to 0", () => {
      cart.add(widgetProduct(), 2);
      cart.updateQuantity("widget", 0);
      expect(cart.itemCount).toBe(0);
      expect(cart.remove("widget")).toBe(false); // no longer present
    });

    it("throws for unknown product id", () => {
      expect(() => cart.updateQuantity("unknown", 5)).toThrow(
        "Product unknown is not in the cart",
      );
    });

    it("rejects negative quantity", () => {
      cart.add(widgetProduct(), 1);
      expect(() => cart.updateQuantity("widget", -1)).toThrow(RangeError);
    });

    it("rejects non-integer quantity", () => {
      cart.add(widgetProduct(), 1);
      expect(() => cart.updateQuantity("widget", 1.5)).toThrow(RangeError);
    });
  });

  describe("clear", () => {
    it("removes all items", () => {
      cart.add(widgetProduct(), 2);
      cart.add(gadgetProduct(), 3);
      cart.clear();
      expect(cart.itemCount).toBe(0);
    });
  });

  describe("snapshot", () => {
    it("returns a deep copy that cannot mutate cart state", () => {
      cart.add(widgetProduct(), 2);
      const snap = cart.snapshot();
      snap[0]!.quantity = 999;
      snap[0]!.product.unitPriceCents = 1;
      expect(cart.itemCount).toBe(2);
      expect(cart.totals().subtotalCents).toBe(2000);
    });
  });
});

// ── Cart.totals() pricing pipeline ──

describe("Cart.totals() pricing pipeline", () => {
  it("computes subtotal as sum of (unitPriceCents * quantity)", () => {
    const cart = new Cart();
    cart.add(widgetProduct(), 3); // 1000 * 3
    cart.add(gadgetProduct(), 2); // 2000 * 2
    const totals = cart.totals();
    expect(totals.subtotalCents).toBe(7000);
  });

  it("returns all zeros for empty cart", () => {
    const cart = new Cart();
    const totals = cart.totals();
    expect(totals).toEqual({
      subtotalCents: 0,
      discountCents: 0,
      taxCents: 0,
      shippingCents: 0,
      totalCents: 0,
    });
  });

  it("applies discount policy and clamps to [0, subtotal]", () => {
    const discount: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(300),
    };
    const cart = new Cart({ discountPolicy: discount });
    cart.add(widgetProduct(), 1); // subtotal = 1000
    const totals = cart.totals();
    expect(totals.discountCents).toBe(300);
    expect(totals.subtotalCents).toBe(1000);
    expect(totals.totalCents).toBe(700); // 1000 - 300
  });

  it("clamps negative discount to 0", () => {
    const discount: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(-50),
    };
    const cart = new Cart({ discountPolicy: discount });
    cart.add(widgetProduct(), 1);
    expect(cart.totals().discountCents).toBe(0);
  });

  it("clamps discount exceeding subtotal to subtotal", () => {
    const discount: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(9999),
    };
    const cart = new Cart({ discountPolicy: discount });
    cart.add(widgetProduct(), 1); // subtotal = 1000
    expect(cart.totals().discountCents).toBe(1000);
    expect(cart.totals().totalCents).toBe(0);
  });

  it("computes tax on discounted subtotal", () => {
    const discount: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(200),
    };
    const tax: TaxCalculator = {
      computeTaxCents: vi.fn().mockReturnValue(80),
    };
    const cart = new Cart({ discountPolicy: discount, taxCalculator: tax });
    cart.add(widgetProduct(), 1); // subtotal 1000, discount 200, discounted 800
    const totals = cart.totals();
    // Tax receives discounted subtotal (800) and region "US"
    expect(tax.computeTaxCents).toHaveBeenCalledWith(800, "US");
    expect(totals.taxCents).toBe(80);
  });

  it("uses configured region for tax", () => {
    const tax: TaxCalculator = {
      computeTaxCents: vi.fn().mockReturnValue(0),
    };
    const cart = new Cart({ taxCalculator: tax, region: "FR" });
    cart.add(widgetProduct(), 1);
    cart.totals();
    expect(tax.computeTaxCents).toHaveBeenCalledWith(1000, "FR");
  });

  it("computes shipping against discounted subtotal and lines", () => {
    const discount: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(500),
    };
    const shipping: ShippingCalculator = {
      computeShippingCents: vi.fn().mockReturnValue(399),
    };
    const cart = new Cart({
      discountPolicy: discount,
      shippingCalculator: shipping,
    });
    cart.add(widgetProduct(), 1); // subtotal 1000, discounted 500
    const totals = cart.totals();
    expect(shipping.computeShippingCents).toHaveBeenCalledWith(
      expect.any(Array),
      500,
    );
    expect(totals.shippingCents).toBe(399);
  });

  it("clamps negative tax to 0", () => {
    const tax: TaxCalculator = {
      computeTaxCents: vi.fn().mockReturnValue(-10),
    };
    const cart = new Cart({ taxCalculator: tax });
    cart.add(widgetProduct(), 1);
    expect(cart.totals().taxCents).toBe(0);
  });

  it("clamps negative shipping to 0", () => {
    const shipping: ShippingCalculator = {
      computeShippingCents: vi.fn().mockReturnValue(-5),
    };
    const cart = new Cart({ shippingCalculator: shipping });
    cart.add(widgetProduct(), 1);
    expect(cart.totals().shippingCents).toBe(0);
  });

  it("totalCents = discountedSubtotal + tax + shipping", () => {
    const discount: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(100),
    };
    const tax: TaxCalculator = {
      computeTaxCents: vi.fn().mockReturnValue(72),
    };
    const shipping: ShippingCalculator = {
      computeShippingCents: vi.fn().mockReturnValue(500),
    };
    const cart = new Cart({
      discountPolicy: discount,
      taxCalculator: tax,
      shippingCalculator: shipping,
    });
    cart.add(widgetProduct(), 1); // subtotal 1000
    const totals = cart.totals();
    // discountedSubtotal = 1000 - 100 = 900
    // total = 900 + 72 + 500 = 1472
    expect(totals.totalCents).toBe(1472);
  });
});

