        check: vi.fn().mockResolvedValue({ available: true }),
      };
      const cart = new Cart();
      cart.add(widgetProduct(), 1);
      cart.add(gadgetProduct(), 2);
      await cart.checkout({ inventoryChecker });
      expect(inventoryChecker.check).toHaveBeenCalledTimes(2);
    });

    it("stops at first denial with multiple items", async () => {
      const inventoryChecker: InventoryChecker = {
        check: vi
          .fn()
          .mockResolvedValueOnce({ available: true })
          .mockResolvedValueOnce({ available: false, reason: "out of stock" }),
      };
      const cart = new Cart();
      cart.add(widgetProduct(), 1);
      cart.add(gadgetProduct(), 2);
      await expect(cart.checkout({ inventoryChecker })).rejects.toThrow(InventoryError);
    });

    it("generates a default message when reason is not provided", async () => {
      const inventoryChecker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({
          available: false,
          availableQuantity: 0,
        }),
      };
      const cart = new Cart();
      cart.add(widgetProduct(), 2);
      try {
        await cart.checkout({ inventoryChecker });
        expect.fail("should have thrown");
      } catch (err) {
        const invErr = err as InventoryError;
        expect(invErr.message).toContain("widget");
        expect(invErr.message).toContain("2");
      }
    });
  });

  describe("async tax provider", () => {
    it("uses AsyncTaxRateProvider to compute tax", async () => {
      const asyncTaxProvider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockResolvedValue(0.10),
      };
      const cart = new Cart({ region: "US" });
      cart.add(widgetProduct(), 1); // subtotal 1000
      const result = await cart.checkout({ asyncTaxProvider });
      expect(result.totals.taxCents).toBe(100);
      expect(asyncTaxProvider.getRate).toHaveBeenCalledWith("US");
    });

    it("async tax is computed on discounted subtotal", async () => {
      const discount: DiscountPolicy = {
        computeDiscountCents: vi.fn().mockReturnValue(200),
      };
      const asyncTaxProvider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockResolvedValue(0.10),
      };
      const cart = new Cart({ discountPolicy: discount, region: "US" });
      cart.add(widgetProduct(), 1); // subtotal 1000, discount 200, discounted 800
      const result = await cart.checkout({ asyncTaxProvider });
      expect(result.totals.taxCents).toBe(80); // 10% of 800
    });

    it("propagates async tax provider errors", async () => {
      const asyncTaxProvider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockRejectedValue(new Error("rate service down")),
      };
      const cart = new Cart();
      cart.add(widgetProduct(), 1);
      await expect(cart.checkout({ asyncTaxProvider })).rejects.toThrow("rate service down");
    });
  });

  describe("full pipeline with all collaborators", () => {
    it("price refresh → inventory check → async tax → totals", async () => {
      const discount: DiscountPolicy = {
        computeDiscountCents: vi.fn().mockReturnValue(100),
      };
      const shipping: ShippingCalculator = {
        computeShippingCents: vi.fn().mockReturnValue(500),
      };
      const priceFetcher: PriceFetcher = {
        fetchPriceCents: vi.fn().mockResolvedValue(1200),
      };
      const inventoryChecker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({ available: true }),
      };
      const asyncTaxProvider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockResolvedValue(0.08),
      };

      const cart = new Cart({
        discountPolicy: discount,
        shippingCalculator: shipping,
        region: "US-TX",
      });
      cart.add(widgetProduct(), 2);

      const result = await cart.checkout({
        priceFetcher,
        inventoryChecker,
        asyncTaxProvider,
      });

      // subtotal: 1200 * 2 = 2400
      expect(result.totals.subtotalCents).toBe(2400);
      // discount: clamped(100) = 100
      expect(result.totals.discountCents).toBe(100);
      // discountedSubtotal: 2400 - 100 = 2300
      // tax: floor(2300 * 0.08) = floor(184) = 184
      expect(result.totals.taxCents).toBe(184);
      // shipping: 500
      expect(result.totals.shippingCents).toBe(500);
      // total: 2300 + 184 + 500 = 2984
      expect(result.totals.totalCents).toBe(2984);

      // Verify collaborators were called
      expect(priceFetcher.fetchPriceCents).toHaveBeenCalledWith("widget");
      expect(inventoryChecker.check).toHaveBeenCalledWith("widget", 2);
      expect(asyncTaxProvider.getRate).toHaveBeenCalledWith("US-TX");
    });
  });

  describe("checkout does not mutate cart state", () => {
    it("original cart lines are unchanged after price refresh", async () => {
      const priceFetcher: PriceFetcher = {
        fetchPriceCents: vi.fn().mockResolvedValue(9999),
      };
      const cart = new Cart();
      cart.add(widgetProduct(), 1);
      await cart.checkout({ priceFetcher });
      // Cart's internal price should still be the original
      expect(cart.totals().subtotalCents).toBe(1000);
    });
  });
});

