import { describe, it, expect } from "vitest";
import {
  NoTaxCalculator,
  RegionalTaxCalculator,
  AsyncTaxCalculator,
  totalLineWeightGrams,
  type AsyncTaxRateProvider,
} from "../src/tax.ts";
import type { CartLine } from "../src/product.ts";
import { vi } from "vitest";

describe("NoTaxCalculator", () => {
  const calc = new NoTaxCalculator();

  it.each([
    [0, "US"],
    [1000, "US"],
    [5000, "FR"],
    [-100, "GB"],
  ])("computeTaxCents(%i, %s) returns 0", (taxable, region) => {
    expect(calc.computeTaxCents(taxable, region)).toBe(0);
  });
});

describe("RegionalTaxCalculator", () => {
  describe("constructor validation", () => {
    it("rejects defaultRate below 0", () => {
      expect(() => new RegionalTaxCalculator({}, -0.01)).toThrow(RangeError);
    });

    it("rejects defaultRate above 1", () => {
      expect(() => new RegionalTaxCalculator({}, 1.01)).toThrow(RangeError);
    });

    it("rejects NaN defaultRate", () => {
      expect(() => new RegionalTaxCalculator({}, NaN)).toThrow(RangeError);
    });

    it("rejects invalid per-region rate", () => {
      expect(() => new RegionalTaxCalculator({ "US": 1.5 })).toThrow(RangeError);
    });

    it("rejects negative per-region rate", () => {
      expect(() => new RegionalTaxCalculator({ "US": -0.1 })).toThrow(RangeError);
    });

    it("accepts valid boundary rates", () => {
      expect(() => new RegionalTaxCalculator({ "US": 0, "FR": 1 }, 0.5)).not.toThrow();
    });
  });

  describe("computeTaxCents", () => {
    const calc = new RegionalTaxCalculator(
      { "US-CA": 0.0875, "FR": 0.20, "JP": 0.10 },
      0.05,
    );

    it.each([
      [1000, "US-CA", 87],   // 1000 * 0.0875 = 87.5, floor → 87
      [1000, "FR", 200],     // 1000 * 0.20 = 200
      [1000, "JP", 100],     // 1000 * 0.10 = 100
      [1000, "DE", 50],      // unknown region → default 0.05
      [999, "US-CA", 87],    // 999 * 0.0875 = 87.4125, floor → 87
    ])("tax on %i cents in %s = %i", (taxable, region, expected) => {
      expect(calc.computeTaxCents(taxable, region)).toBe(expected);
    });

    it("returns 0 for zero taxable amount", () => {
      expect(calc.computeTaxCents(0, "FR")).toBe(0);
    });

    it("returns 0 for negative taxable amount", () => {
      expect(calc.computeTaxCents(-100, "FR")).toBe(0);
    });

    it("uses 0 as default rate when defaultRate is omitted", () => {
      const noDefault = new RegionalTaxCalculator({ "US": 0.10 });
      expect(noDefault.computeTaxCents(1000, "UNKNOWN")).toBe(0);
    });
  });
});

describe("AsyncTaxCalculator", () => {
  it("computes tax with a resolved rate", async () => {
    const provider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.10),
    };
    const calc = new AsyncTaxCalculator(provider);
    const tax = await calc.computeTaxCents(1000, "US");
    expect(tax).toBe(100);
    expect(provider.getRate).toHaveBeenCalledWith("US");
  });

  it("floors the computed tax", async () => {
    const provider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.0875),
    };
    const calc = new AsyncTaxCalculator(provider);
    // 999 * 0.0875 = 87.4125 → 87
    expect(await calc.computeTaxCents(999, "US-CA")).toBe(87);
